/**
 * Shared contract for the Trello-style board. Plain data only.
 *
 * @typedef {Object} Card
 * @property {number} id        unique across the board
 * @property {string} title
 * @property {string[]} labels  free-form tags, e.g. ['bug']
 * @property {string} listId    id of the list currently holding the card
 *
 * @typedef {Object} List
 * @property {string} id        kebab-case slug of the title, e.g. 'in-progress'
 * @property {string} title
 * @property {Card[]} cards     in display order, top to bottom
 *
 * @typedef {Object} BoardSnapshot
 * @property {List[]} lists     in display order, left to right
 */

/** Lists a new board starts with when none are given. */
const DEFAULT_LISTS = Object.freeze(['To Do', 'In Progress', 'Done'])

/** Turns a list title into its id: lowercase, non-alphanumerics collapsed to '-'. */
function slugify(title) {
  return String(title).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
}

module.exports = { DEFAULT_LISTS, slugify }

/** The board store: ordered lists of ordered cards. */

/**
 * @param {{ lists?: string[] }} [options] list titles; defaults to DEFAULT_LISTS
 * @returns {{
 *   snapshot(): import('../board/contract.js').BoardSnapshot,
 *   addList(title: string): import('../board/contract.js').List,
 *   addCard(listId: string, title: string, options?: { labels?: string[] }): import('../board/contract.js').Card | null,
 *   moveCard(cardId: number, toListId: string, toIndex?: number): import('../board/contract.js').Card | null,
 *   removeCard(cardId: number): boolean,
 * }}
 * snapshot() returns deep copies. addCard/moveCard return null for an unknown list or card.
 * moveCard appends when toIndex is omitted and clamps it into range otherwise.
 */
function createBoard(options = {}) {
  throw new Error('createBoard: not implemented')
}

module.exports = { createBoard }

/**
 * Renders a BoardSnapshot as side-by-side text columns, one per list.
 * Each column header shows the list title and card count, e.g. 'To Do (2)'.
 * Each card shows '#<id> <title>' and its labels as '[label]'. An empty list shows '(empty)'.
 * Titles longer than columnWidth are truncated with '...'.
 *
 * @param {import('../../board/contract.js').BoardSnapshot} board
 * @param {{ columnWidth?: number }} [options] default 24
 * @returns {string}
 */
function renderBoard(board, options = {}) {
  throw new Error('renderBoard: not implemented')
}

module.exports = { renderBoard }

/**
 * Shared shapes for the Trello-style board.
 *
 * @typedef {'todo' | 'doing' | 'done'} ColumnId
 *
 * @typedef {Object} Card
 * @property {number} id
 * @property {string} title
 * @property {ColumnId} column
 *
 * @typedef {Object} Column
 * @property {ColumnId} id
 * @property {string} title   Display title, from COLUMN_TITLES
 * @property {Card[]} cards   In insertion/move order; a moved card goes to the end
 *
 * @typedef {Object} Board
 * @property {Column[]} columns  Always all of COLUMNS, in COLUMNS order, even when empty
 */

/** Column ids in display order. */
const COLUMNS = Object.freeze(['todo', 'doing', 'done'])

/** Display title per column id. */
const COLUMN_TITLES = Object.freeze({ todo: 'To Do', doing: 'Doing', done: 'Done' })

function isColumn(value) {
  return COLUMNS.includes(value)
}

module.exports = { COLUMNS, COLUMN_TITLES, isColumn }

/** The board store. Stub: implemented by task board-store. */
// eslint-disable-next-line no-unused-vars
const { COLUMNS, COLUMN_TITLES, isColumn } = require('./board-types.js')

/**
 * Creates an independent board. Card ids start at 1 per board.
 * @returns {{
 *   addCard(title: string, column?: import('./board-types.js').ColumnId): import('./board-types.js').Card,
 *   moveCard(id: number, to: import('./board-types.js').ColumnId): import('./board-types.js').Card | null,
 *   removeCard(id: number): boolean,
 *   snapshot(): import('./board-types.js').Board,
 * }}
 * addCard defaults column to 'todo' and throws on an unknown column or empty title.
 * moveCard returns null for an unknown id, throws on an unknown column, appends to the target column.
 * snapshot returns a deep copy; mutating it never changes the board.
 */
function createBoard() {
  throw new Error('not implemented: createBoard')
}

module.exports = { createBoard }

/** Renders a Board snapshot as plain text. Stub: implemented by task board-render. */

/**
 * Output format, one block per column in board.columns order, blocks joined by a blank line:
 *   == To Do (2) ==
 *   - #1 first card
 *   - #3 another
 * An empty column renders its header followed by the line "  (empty)".
 * @param {import('../../lib/board-types.js').Board} board
 * @returns {string}
 */
function renderBoard(board) {
  throw new Error('not implemented: renderBoard')
}

module.exports = { renderBoard }
